import{_ as i,l as o,o as e,c as l,v as t,p as n,x as r,d as A,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"矩阵范数与扰动","description":"","frontmatter":{"title":"矩阵范数与扰动","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/matrix-norm-perturb.md","filePath":"cs/matrix-norm-perturb.md","lastUpdated":1789023840000}'),h={name:"cs/matrix-norm-perturb.md"};function c(m,a,u,x,_,E){const p=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="矩阵范数与扰动" tabindex="-1">矩阵范数与扰动 <a class="header-anchor" href="#矩阵范数与扰动" aria-label="Permalink to &quot;矩阵范数与扰动&quot;">​</a></h1><div class="epigraph"><p>向量范数量解的大小；算子范数量矩阵作为映射能拉伸多少。两者一起，才写出 $Ax=b$ 的条件数与扰动界。</p><footer>—— 据 Trefethen and Bau, Numerical Linear Algebra；Golub and Van Loan, Matrix Computations；Higham, Accuracy and Stability of Numerical Algorithms 整理</footer></div><p>上一课<a href="/cs/gaussian-pivoting">高斯消元与主元</a>给出带主元的 \\(LU\\)。本课不重做换行，也不从抽象赋范空间另起。缺口是：条件数课留下了「\\(A\\) 接近奇异则病态」，<strong>还没有可计算的 \\(\\kappa(A)=\\|A\\|\\,\\|A^{-1}\\|\\)</strong>，因而无法把残量翻译成解的误差界。消元的后向扰动 \\(\\Delta A\\) 要用同一种范数来读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>向量范数 \\(\\|\\cdot\\|\\) 给 \\(x\\) 一个尺度。诱导矩阵范数 \\(\\|A\\|=\\sup_{x\\neq 0}\\|Ax\\|/\\|x\\|\\)，于是 \\(\\|Ax\\|\\le\\|A\\|\\,\\|x\\|\\)。缺口因此不是再列三种常见范数的公式，而是<strong>让扰动定理能开口</strong>：若 \\((A+\\Delta A)(x+\\delta x)=b+\\delta b\\)，则在合适小性条件下，相对 \\(\\|\\delta x\\|/\\|x\\|\\) 被 \\(\\kappa(A)\\) 乘上数据的相对扰动（再除以 \\(1-\\kappa\\|\\Delta A\\|/\\|A\\|\\) 一类因子）控制。上一课的残量对应某种 \\(\\delta b\\) 或 \\(\\Delta A\\)；没有范数，残量只是一串数。</p><p>常用：\\(\\|\\cdot\\|_2\\) 与谱，\\(\\|\\cdot\\|_\\infty\\) 与行和，\\(\\|\\cdot\\|_1\\) 与列和。本课只要求：一旦选定，条件数与后向误差用同一个。换范数会改 \\(\\kappa\\) 的数值，不改「病态」的定性，只要范数等价。</p><h3 id="范数大不是「矩阵更病态」" tabindex="-1">范数大不是「矩阵更病态」 <a class="header-anchor" href="#范数大不是「矩阵更病态」" aria-label="Permalink to &quot;范数大不是「矩阵更病态」&quot;">​</a></h3><p>\\(\\|A\\|\\) 大可以被缩放解释；\\(A^{-1}\\) 同时变小。病态是乘积 \\(\\kappa\\)。只看行列式、只看最小对角元，都会误判。特征值接近 0 在 2-范数下与 \\(\\kappa_2=\\sigma_{\\max}/\\sigma_{\\min}\\) 相关，但非正规矩阵的特征值可以骗人——本课点名奇异值比特征值更贴 \\(\\kappa_2\\)，不把 SVD 课写完。</p><p><span class="marginnote">Trefethen and Bau 前几讲就是范数、\\(\\kappa\\)、后向稳定。Golub and Van Loan 给出标准扰动定理。Higham 把同一界接到实际残量。本课不证完备性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 \\(Ax=b\\)，\\(A\\) 可逆：\\(\\kappa(A)=\\|A\\|\\,\\|A^{-1}\\|\\ge 1\\)。相对后向误差小则相对前向误差 \\(\\lesssim\\kappa\\) 倍。残量 \\(r=b-A\\hat x\\) 满足 \\(A(x-\\hat x)=r\\)，故 \\(\\|x-\\hat x\\|/\\|x\\|\\le\\kappa\\,\\|r\\|/(\\|A\\|\\,\\|x\\|)\\)。这把消元课的「看残量」接成可算的前向估计。</p>',11)),(e(),n(d,null,{default:r(()=>[s(p,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%9F%A9%E9%98%B5%20A%22%5D%20--%3E%20KAPPA%5B%22%E6%9D%A1%E4%BB%B6%E6%95%B0%E7%AD%89%E4%BA%8E%20A%20%E8%8C%83%E6%95%B0%E4%B9%98%20A%20%E9%80%86%E8%8C%83%E6%95%B0%22%5D%0A%20%20DLT%5B%22%E5%90%8E%E5%90%91%E6%89%B0%E5%8A%A8%22%5D%20--%3E%20BND%5B%22%E6%89%B0%E5%8A%A8%E5%AE%9A%E7%90%86%22%5D%0A%20%20KAPPA%20--%3E%20BND%0A%20%20BND%20--%3E%20FWD%5B%22%E8%A7%A3%E7%9A%84%E7%9B%B8%E5%AF%B9%E8%AF%AF%E5%B7%AE%E7%95%8C%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>预条件、平衡缩放，是在换一个 \\(\\kappa\\) 更小的等价问题再解。那是算法策略，问题 \\(Ax=b\\) 的原始 \\(\\kappa\\) 仍在；你交回去的 \\(\\hat x\\) 仍要用原 \\(A\\) 来解释。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>诱导范数把矩阵当成最坏方向上的拉伸。\\(A^{-1}\\) 的拉伸是「解对数据有多敏感」的另一半。两者相乘，正好是条件数课在线性映射上的实例。消元即使后向稳定，只保证 \\(\\Delta A\\) 相对 \\(\\|A\\|\\) 为 \\(O(u)\\)；乘上 \\(\\kappa\\) 之后，前向仍可丢掉所有位数。迭代法下一课会用同一套范数谈收缩：收敛的是误差在某种范数下变小。</p><p>分量扰动与范数扰动可以给出不同图像：某几个未知量极敏感，其它不敏感时，范数 \\(\\kappa\\) 会把最坏方向当成全体。分量条件数更细，本课不展开，但解释了「残量还可以、个别分量已经飞了」。平衡（对行或列对角缩放）改变 \\(\\kappa\\) 的数值，是合法的预处理：你解的是缩放后的系统，再把解缩放回去。迭代法下一课用 \\(\\|G\\|\\) 谈收缩，用的是同一套诱导范数；谱半径给出更紧的渐近，瞬态仍可能先由范数描述。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有等价范数不等式列完，不讲分量条件数。下一课<a href="/cs/iterative-solver-converge">迭代法何时收敛</a>用谱半径与范数讨论迭代。后课默认：\\(Ax=b\\) 的 \\(\\kappa(A)=\\|A\\|\\,\\|A^{-1}\\|\\)；残量界要连同 \\(\\kappa\\) 读；主元不降低这个 \\(\\kappa\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>诱导范数给矩阵一个拉伸量；\\(\\kappa\\) 是 \\(\\|A\\|\\,\\|A^{-1}\\|\\)。</li><li>后向扰动经 \\(\\kappa\\) 变成前向误差界。</li><li>残量小且 \\(\\kappa\\) 大时，解仍可以差。</li><li>下一课用范数看迭代误差是否收缩。</li><li>出处：Trefethen and Bau；Golub and Van Loan；Higham。</li></ul>',8))])}const B=i(h,[["render",c]]);export{b as __pageData,B as default};
